import { apiClient } from "./api-client"

export type InvoicePdfFormat = "A4" | "A5" | "80mm"

async function pdfBlobFrom(response: Response): Promise<Blob> {
  const blob = await response.blob()
  if (blob.type !== "application/pdf" || blob.size < 1_000) {
    throw new Error("The server returned an invalid invoice PDF")
  }
  return blob
}

/** Fetch the authoritative PDF bytes generated by the backend. */
export async function getInvoicePdfBlob(saleId: string | number, format: InvoicePdfFormat = "A4"): Promise<Blob> {
  return pdfBlobFrom(await apiClient.getInvoicePdf(saleId, format))
}

/**
 * CIS/VSDC spec §7.18/§15: "print only one original receipt. Reprint shall
 * have a watermark with mention Copy." Registers this deliberate issuance with
 * the backend, then fetches the PDF: the first registered issuance of a sale
 * is the original, every later one comes back as its CS/CR copy.
 */
export async function issueInvoicePdfBlob(saleId: string | number, format: InvoicePdfFormat = "A4"): Promise<Blob> {
  await apiClient.reprintSale(saleId)
  return getInvoicePdfBlob(saleId, format)
}

export interface ReceiptCopyPdf {
  blob: Blob
  filename: string
  copyLabel: "CS" | "CR" | null
}

/** Explicit CS/CR copy of an existing NS/NR receipt (original fiscal data, marked COPY). */
export async function getReceiptCopyPdf(saleId: string | number, format: InvoicePdfFormat = "A4"): Promise<ReceiptCopyPdf> {
  const response = await apiClient.printReceiptCopy(saleId, format)
  const disposition = response.headers.get("Content-Disposition") ?? ""
  const label = response.headers.get("X-Receipt-Copy-Label")
  const blob = await pdfBlobFrom(response)
  const filename = disposition.match(/filename="([^"]+)"/)?.[1]
    ?? `EBM-${label ?? "Receipt"}-Copy-${saleId}${format === "A4" ? "" : `-${format}`}.pdf`
  return { blob, filename, copyLabel: label === "CS" || label === "CR" ? label : null }
}

/** Opens a PDF blob in a new tab and triggers the browser print dialog. */
export function printPdfBlob(blob: Blob): boolean {
  const url = URL.createObjectURL(blob)
  const printWindow = window.open(url, "_blank")
  if (!printWindow) {
    URL.revokeObjectURL(url)
    return false
  }
  printWindow.onload = () => {
    printWindow.print()
    setTimeout(() => URL.revokeObjectURL(url), 60_000)
  }
  return true
}

function saveBlob(blob: Blob, filename: string): void {
  const url = URL.createObjectURL(blob)
  const link = document.createElement("a")
  link.href = url
  link.download = filename
  document.body.appendChild(link)
  link.click()
  link.remove()
  setTimeout(() => URL.revokeObjectURL(url), 2_000)
}

/** Downloads the explicit CS/CR copy; returns the label the backend assigned. */
export async function downloadReceiptCopy(saleId: string | number, format: InvoicePdfFormat = "A4"): Promise<"CS" | "CR" | null> {
  const copy = await getReceiptCopyPdf(saleId, format)
  saveBlob(copy.blob, copy.filename)
  return copy.copyLabel
}

/** Prints the explicit CS/CR copy; returns the label the backend assigned. */
export async function printReceiptCopy(saleId: string | number, format: InvoicePdfFormat = "A4"): Promise<"CS" | "CR" | null> {
  const copy = await getReceiptCopyPdf(saleId, format)
  if (!printPdfBlob(copy.blob)) throw new Error("Allow pop-ups to print the receipt copy")
  return copy.copyLabel
}

/**
 * Whether a sale's receipt is an NS/NR that can be reprinted as CS/CR. The
 * backend re-checks this plus the stored VSDC fiscal record.
 */
export function canCopyReceipt(sale: { rcptLabel?: string | null; isProforma?: boolean; status?: string }): boolean {
  if (sale.isProforma) return false
  if (sale.rcptLabel && sale.rcptLabel !== "NS" && sale.rcptLabel !== "NR") return false
  return !["CANCELLED", "DRAFT", "PENDING", "CONVERTED"].includes(sale.status ?? "")
}

/** "first is original, rest are COPY" — see {@link issueInvoicePdfBlob}. */
export async function downloadInvoicePdf(
  saleId: string | number,
  filename: string,
  format: InvoicePdfFormat = "A4",
): Promise<boolean> {
  saveBlob(await issueInvoicePdfBlob(saleId, format), filename)
  return true
}

/** Same "first is original, rest are COPY" registration as {@link downloadInvoicePdf} — sharing hands out a receipt file too. */
export async function shareInvoicePdf(
  saleId: string | number,
  filename: string,
  format: InvoicePdfFormat = "A4",
): Promise<boolean> {
  const blob = await issueInvoicePdfBlob(saleId, format)
  const file = new File([blob], filename, { type: "application/pdf" })
  const shareData: ShareData = { title: filename.replace(/\.pdf$/i, ""), files: [file] }

  if (typeof navigator.share === "function" && (!navigator.canShare || navigator.canShare(shareData))) {
    await navigator.share(shareData)
    return true
  }

  saveBlob(blob, filename)
  return false
}
